        "from collections import Counter\n",
        "import os\n",
        "\n",
        "labels_path = \"/content/road_damage_dataset/train/labels\"\n",
        "\n",
        "class_counts = Counter()\n",
        "\n",
        "for filename in os.listdir(labels_path):\n",
        "    if filename.endswith(\".txt\"):\n",
        "        with open(os.path.join(labels_path, filename), \"r\") as f:\n",
        "            for line in f:\n",
        "                parts = line.strip().split()\n",
        "                if parts:\n",
        "                    class_id = int(parts[0])\n",
        "                    class_counts[class_id] += 1\n",
        "\n",
        "print(\"✅ Class annotation counts:\")\n",
        "\n",
        "for class_id, count in sorted(class_counts.items()):\n",
        "    class_name = data[\"names\"][class_id]\n",
        "    print(f\"Class {class_id} ({class_name}): {count}\")"
